class MovingAverage
{
    queue<int> window;
    int capacity;
    long long sum = 0;
public:
    MovingAverage(int size) : capacity(size) {}
    double next(int val)
    {
        window.push(val);
        sum += val;
        if ((int)window.size() > capacity)
        {
            sum -= window.front();
            window.pop();
        }
        return (double)sum / window.size();
    }
};
